'use strict';

// MODULES //

var isRealFloatingPointDataType = require( '@stdlib/ndarray/base/assert/is-real-floating-point-data-type' );
var isComplexFloatingPointDataType = require( '@stdlib/ndarray/base/assert/is-complex-floating-point-data-type' );
var isSignedIntegerDataType = require( '@stdlib/ndarray/base/assert/is-signed-integer-data-type' );
var isUnsignedIntegerDataType = require( '@stdlib/ndarray/base/assert/is-unsigned-integer-data-type' );
var isBooleanDataType = require( '@stdlib/ndarray/base/assert/is-boolean-data-type' );


// VARIABLES //

var COMPLEX64_NAN = require( '@stdlib/constants/complex64/nan' );
var COMPLEX128_NAN = require( '@stdlib/constants/complex128/nan' );
var INT8_MAX = require( '@stdlib/constants/int8/max' );
var INT16_MAX = require( '@stdlib/constants/int16/max' );
var INT32_MAX = require( '@stdlib/constants/int32/max' );
var UINT8_MAX = require( '@stdlib/constants/uint8/max' );
var UINT16_MAX = require( '@stdlib/constants/uint16/max' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );


// MAIN //

/**
* Returns a default sentinel value based on data type.
*
* @param {string} dtype - data type
* @returns {*} sentinel value
*
* @example
* var v = getSentinelValue( 'float64' );
* // returns NaN
*
* @example
* var v = getSentinelValue( 'int32' );
* // returns 2147483647
*
* @example
* var v = getSentinelValue( 'bool' );
* // returns false
*/
function getSentinelValue( dtype ) {
	if ( isComplexFloatingPointDataType( dtype ) ) {
		if ( dtype === 'complex128' ) {
			return COMPLEX128_NAN;
		}
		return COMPLEX64_NAN;
	}
	if ( isRealFloatingPointDataType( dtype ) ) {
		return NaN;
	}
	if (
		isSignedIntegerDataType( dtype ) ||
		isUnsignedIntegerDataType( dtype )
	) {
		if ( dtype === 'int8' ) {
			return INT8_MAX;
		}
		if ( dtype === 'uint8' ) {
			return UINT8_MAX;
		}
		if ( dtype === 'int16' ) {
			return INT16_MAX;
		}
		if ( dtype === 'uint16' ) {
			return UINT16_MAX;
		}
		if ( dtype === 'int32' ) {
			return INT32_MAX;
		}
		if ( dtype === 'uint32' ) {
			return UINT32_MAX;
		}
	}
	if ( isBooleanDataType( dtype ) ) {
		return false;
	}
	return NaN;
}


// EXPORTS //

module.exports = getSentinelValue;
